        "Pablo Pérez‐Piñera"
      ],
      "doi": "10.1016/j.ymthe.2020.01.005",
      "source": "Molecular Therapy",
      "title": "Treatment of a Mouse Model of ALS by In Vivo Base Editing",
      "work_id": "doi:10.1016/j.ymthe.2020.01.005",
      "year": 2020
    }
  },
  {
    "artifact_path": "canonical/works.parquet",
