      "source": "Nature Communications",
      "title": "Mutant FUS causes DNA ligation defects to inhibit oxidative damage repair in Amyotrophic Lateral Sclerosis",
      "work_id": "doi:10.1038/s41467-018-06111-6",
      "year": 2018
    }
