        "Paul M. McKeever",
        "Rahul Kumar",
        "Julie Schwartz",
        "Mahshad Kolahdouzan",
        "Carol X Chen"
      ],
      "doi": "10.7554/elife.48363",
      "source": "eLife",
      "title": "Implementation of an antibody characterization procedure and application to the major ALS/FTD disease gene C9ORF72",
      "work_id": "doi:10.7554/elife.48363",
      "year": 2019
    }
